contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address newCEO, address other) public {
        require(newCEO != other);
        bool firstRevert;
        assembly { firstRevert := 1 }
        try c.DrugDealer{value: 0}(newCEO) returns () { firstRevert = false; } catch { }
        require(!firstRevert);
        if (address(this).balance > 0) {
            payable(address(0)).transfer(address(this).balance);
        }
        bool secondRevert;
        assembly { secondRevert := 1 }
        try c.DrugDealer{value: 0}(other) returns () { secondRevert = false; } catch { }
        assert(!secondRevert == false);
    }
    fallback() external payable {}
    receive() external payable {}
}

