pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address initialCEO, address newCEO) public {
        // Ensure initialCEO is not address(0) to act as a valid first CEO
        vm.assume(initialCEO != address(0));
        // newCEO is the msg.sender for DrugDealer, must also not be zero
        vm.assume(newCEO != address(0));
        // newCEO must equal the current ceoAddress for the call to succeed; fuzzer searches this space

        // Initialize ceoAddress to a non-zero initial CEO
        vm.prank(initialCEO);
        c.DrugDealer();

        // Record current ceoAddress before the fuzzed call
        address currentCEO = c.ceoAddress();

        // Fuzzed caller newCEO attempts DrugDealer; call succeeds only if newCEO == currentCEO
        vm.prank(newCEO);
        try c.DrugDealer() { 
            // Call succeeded, so newCEO == currentCEO
            // Assert that ceoAddress now equals newCEO (the actual caller)
            assertEq(c.ceoAddress(), newCEO, "ceoAddress must equal msg.sender after successful DrugDealer");
        } catch {
            // Call reverted, so newCEO != currentCEO, no state change expected
            // Assert ceoAddress did not change (it should equal currentCEO)
            assertEq(c.ceoAddress(), currentCEO, "ceoAddress must not change on failed DrugDealer");
        }
    }
}

