pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26);
        vm.assume(caller != address(0));
        vm.assume(caller.code.length == 0);
        // Make caller the current ceoAddress so the require passes
        vm.prank(0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26);
        c.DrugDealer();
        // Now ceoAddress is 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26, caller is the new CEO candidate
        vm.prank(caller);
        c.DrugDealer();
        // After the call, the reference updates ceoAddress to caller, the mutant leaves it as the initial address
        assertTrue(c.ceoAddress() == caller);
    }
}
